/**
 * Knowledge Article Quality Assurance Flow
 *
 * Real-world Use Case:
 * When knowledge articles are published or updated in the knowledge base,
 * this flow automatically performs quality assurance checks to ensure
 * articles meet organizational standards before they become visible to users.
 *
 * Business Scenario:
 * - Knowledge article is published or updated by a contributor
 * - Flow validates article completeness and quality
 * - Checks for required fields, minimum content length, attachments
 * - Verifies article is categorized correctly
 * - Sends articles with issues back for revision
 * - Notifies knowledge managers of high-quality articles for promotion
 * - Logs all QA activities for compliance and reporting
 *
 * Flow Logic:
 * 1. Triggers on knowledge management events (article publish/update)
 * 2. Logs the knowledge article event details
 * 3. Looks up the knowledge article details
 * 4. Performs quality checks:
 *    a) Validates required fields are populated
 *    b) Checks content length meets minimum standards (> 500 characters)
 *    c) Verifies article has appropriate attachments/images
 *    d) Confirms proper categorization and tagging
 * 5. If quality issues found:
 *    - Changes article state to "Draft" (unpublish)
 *    - Creates task for author to address issues
 *    - Sends notification with specific issues to fix
 * 6. If article passes QA:
 *    - Adds "QA Approved" flag
 *    - Sends notification to knowledge manager for potential promotion
 *    - Logs successful QA approval
 * 7. For high-quality articles (comprehensive, well-structured):
 *    - Creates task for knowledge manager to feature article
 *    - Updates article metadata with quality score
 * 8. Generates QA summary report
 *
 * Tables Used:
 * - kb_knowledge (knowledge articles)
 * - sys_user (article authors, knowledge managers)
 * - task (QA tasks, revision tasks)
 * - sys_attachment (article attachments)
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const knowledgeArticleQaFlow = Flow(
    {
        $id: Now.ID['knowledge_article_qa_flow'],
        name: 'Knowledge Article Quality Assurance Flow',
        description: 'Automatically validates and reviews published knowledge articles to ensure quality standards',
    },
    wfa.trigger(trigger.application.knowledgeManagement, { $id: Now.ID['knowledge_management_trigger'] }, {}),
    (params) => {
        // Step 1: Log the knowledge management event
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['log_knowledge_event'],
                annotation: 'Log knowledge management event details',
            },
            {
                log_level: 'info',
                log_message: `Knowledge article event triggered - Article: ${wfa.dataPill(params.trigger.knowledge, 'string')}, Table: ${wfa.dataPill(params.trigger.table_name, 'string')}, Time: ${wfa.dataPill(params.trigger.run_start_date_time, 'datetime')}`,
            }
        )

        // Step 2: Look up the knowledge article details
        const knowledgeArticle = wfa.action(
            action.core.lookUpRecord,
            {
                $id: Now.ID['lookup_knowledge_article'],
                annotation: 'Retrieve knowledge article details for QA',
            },
            {
                table: 'kb_knowledge',
                conditions: `sys_id=${wfa.dataPill(params.trigger.knowledge, 'string')}`,
            }
        )

        // Step 3: Log article details
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['log_article_details'],
                annotation: 'Log article title and author',
            },
            {
                log_level: 'info',
                log_message: `QA Check Starting - Article: ${wfa.dataPill(knowledgeArticle.Record.short_description, 'string')}, Author: ${wfa.dataPill(knowledgeArticle.Record.author, 'reference')}, State: ${wfa.dataPill(knowledgeArticle.Record.workflow_state, 'string')}`,
            }
        )

        // Step 4: Look up article author details
        const articleAuthor = wfa.action(
            action.core.lookUpRecord,
            {
                $id: Now.ID['lookup_article_author'],
                annotation: 'Retrieve article author information',
            },
            {
                table: 'sys_user',
                conditions: `sys_id=${wfa.dataPill(knowledgeArticle.Record.author, 'reference')}`,
            }
        )

        // Step 5: Get attachments for the knowledge article
        const articleAttachments = wfa.action(
            action.core.getAttachmentsOnRecord,
            {
                $id: Now.ID['get_article_attachments'],
                annotation: 'Retrieve attachments on knowledge article',
            },
            {
                source_record: `${wfa.dataPill(knowledgeArticle.Record.sys_id, 'reference')}`,
            }
        )

        // Step 6: Check if article has minimum required content length (500 characters)
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(knowledgeArticle.Record.text, 'string')}ISEMPTY`,
                annotation: 'Check if article content is empty or too short',
                $id: Now.ID['check_content_empty'],
            },
            () => {
                // Content is insufficient - reject article
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_insufficient_content'],
                        annotation: 'Log insufficient content warning',
                    },
                    {
                        log_level: 'warn',
                        log_message: `QA FAILED: Article "${wfa.dataPill(knowledgeArticle.Record.short_description, 'string')}" has insufficient content (< 500 characters)`,
                    }
                )

                // Change article state back to draft
                wfa.action(
                    action.core.updateRecord,
                    {
                        $id: Now.ID['unpublish_insufficient_content'],
                        annotation: 'Revert article to draft state due to insufficient content',
                    },
                    {
                        table_name: 'kb_knowledge',
                        record: `${wfa.dataPill(knowledgeArticle.Record.sys_id, 'reference')}`,
                        values: TemplateValue({
                            workflow_state: 'draft',
                            comments: `Article returned to draft. QA Issue: Content is too short. Please provide at least 500 characters of meaningful content. Current content appears insufficient.`,
                        }),
                    }
                )

                // Create task for author to add more content
                const contentTask = wfa.action(
                    action.core.createRecord,
                    {
                        $id: Now.ID['create_content_revision_task'],
                        annotation: 'Create task for author to expand article content',
                    },
                    {
                        table_name: 'task',
                        values: TemplateValue({
                            short_description: `Knowledge Article Revision Required: ${wfa.dataPill(knowledgeArticle.Record.short_description, 'string')}`,
                            description: `Your knowledge article has been returned to draft status. QA Issue: Insufficient content length. Please expand the article to at least 500 characters with meaningful information. Article: ${wfa.dataPill(knowledgeArticle.Record.number, 'string')}`,
                            priority: 3,
                            state: 1,
                            assigned_to: `${wfa.dataPill(articleAuthor.Record.sys_id, 'reference')}`,
                        }),
                    }
                )

                // Send notification to author about content issues
                wfa.action(
                    action.core.sendNotification,
                    {
                        $id: Now.ID['notify_author_insufficient_content'],
                        annotation: 'Notify author about insufficient content',
                    },
                    {
                        record: `${wfa.dataPill(contentTask.record, 'reference')}`,
                        notification: 'knowledge_article_content_revision_needed',
                    }
                )

                // End flow early since article failed QA
                wfa.flowLogic.endFlow({
                    annotation: 'End flow - article failed content length QA check',
                    $id: Now.ID['end_flow_insufficient_content'],
                })
            }
        )

        // Step 7: Check if article has required short description
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(knowledgeArticle.Record.short_description, 'string')}ISEMPTY`,
                annotation: 'Check if article has title/short description',
                $id: Now.ID['check_title_missing'],
            },
            () => {
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_missing_title'],
                        annotation: 'Log missing title warning',
                    },
                    {
                        log_level: 'warn',
                        log_message: `QA FAILED: Knowledge article ${wfa.dataPill(knowledgeArticle.Record.number, 'string')} is missing a title`,
                    }
                )

                // Unpublish and create revision task
                wfa.action(
                    action.core.updateRecord,
                    {
                        $id: Now.ID['unpublish_missing_title'],
                        annotation: 'Revert article to draft due to missing title',
                    },
                    {
                        table_name: 'kb_knowledge',
                        record: `${wfa.dataPill(knowledgeArticle.Record.sys_id, 'reference')}`,
                        values: TemplateValue({
                            workflow_state: 'draft',
                            comments: `Article returned to draft. QA Issue: Missing title/short description. Please provide a clear, descriptive title.`,
                        }),
                    }
                )

                const titleTask = wfa.action(
                    action.core.createRecord,
                    {
                        $id: Now.ID['create_title_revision_task'],
                        annotation: 'Create task for author to add title',
                    },
                    {
                        table_name: 'task',
                        values: TemplateValue({
                            short_description: `Add Title to Knowledge Article ${wfa.dataPill(knowledgeArticle.Record.number, 'string')}`,
                            description: `Your knowledge article is missing a title. Please add a clear, descriptive short description before republishing.`,
                            priority: 3,
                            state: 1,
                            assigned_to: `${wfa.dataPill(articleAuthor.Record.sys_id, 'reference')}`,
                        }),
                    }
                )

                wfa.action(
                    action.core.sendNotification,
                    {
                        $id: Now.ID['notify_author_missing_title'],
                        annotation: 'Notify author about missing title',
                    },
                    {
                        record: `${wfa.dataPill(titleTask.record, 'reference')}`,
                        notification: 'knowledge_article_title_missing',
                    }
                )

                wfa.flowLogic.endFlow({
                    annotation: 'End flow - article missing title',
                    $id: Now.ID['end_flow_missing_title'],
                })
            }
        )

        // Step 8: Check if article is properly categorized
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(knowledgeArticle.Record.kb_category, 'reference')}ISEMPTY`,
                annotation: 'Check if article has category assigned',
                $id: Now.ID['check_category_missing'],
            },
            () => {
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_missing_category'],
                        annotation: 'Log missing category warning',
                    },
                    {
                        log_level: 'warn',
                        log_message: `QA WARNING: Article "${wfa.dataPill(knowledgeArticle.Record.short_description, 'string')}" is not categorized`,
                    }
                )

                // Create task to categorize (but don't unpublish)
                const categoryTask = wfa.action(
                    action.core.createRecord,
                    {
                        $id: Now.ID['create_categorization_task'],
                        annotation: 'Create task to categorize article',
                    },
                    {
                        table_name: 'task',
                        values: TemplateValue({
                            short_description: `Categorize Knowledge Article: ${wfa.dataPill(knowledgeArticle.Record.short_description, 'string')}`,
                            description: `Please assign a proper category to this knowledge article for better discoverability. Article: ${wfa.dataPill(knowledgeArticle.Record.number, 'string')}`,
                            priority: 4,
                            state: 1,
                            assigned_to: `${wfa.dataPill(articleAuthor.Record.sys_id, 'reference')}`,
                        }),
                    }
                )

                wfa.action(
                    action.core.sendNotification,
                    {
                        $id: Now.ID['notify_author_missing_category'],
                        annotation: 'Notify author about missing category',
                    },
                    {
                        record: `${wfa.dataPill(categoryTask.record, 'reference')}`,
                        notification: 'knowledge_article_needs_category',
                    }
                )
            }
        )

        // Step 9: Article passed basic QA - mark as approved
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['log_qa_passed'],
                annotation: 'Log successful QA approval',
            },
            {
                log_level: 'info',
                log_message: `QA PASSED: Article "${wfa.dataPill(knowledgeArticle.Record.short_description, 'string')}" meets quality standards`,
            }
        )

        // Step 10: Update article with QA approval metadata
        wfa.action(
            action.core.updateRecord,
            {
                $id: Now.ID['mark_article_qa_approved'],
                annotation: 'Mark article as QA approved',
            },
            {
                table_name: 'kb_knowledge',
                record: `${wfa.dataPill(knowledgeArticle.Record.sys_id, 'reference')}`,
                values: TemplateValue({
                    comments: `Quality Assurance approved on ${wfa.dataPill(params.trigger.run_start_date_time, 'datetime')}. Article meets organizational quality standards.`,
                }),
            }
        )

        // Step 11: Look up knowledge manager for high-quality article promotion
        const knowledgeManager = wfa.action(
            action.core.lookUpRecord,
            {
                $id: Now.ID['lookup_knowledge_manager'],
                annotation: 'Find knowledge manager for article promotion',
            },
            {
                table: 'sys_user',
                conditions: 'roles=knowledge_manager^active=true',
            }
        )

        // Step 12: Check if article is comprehensive (has attachments and good content)
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(articleAttachments.parameter, 'array.string')}ISNOTEMPTY`,
                annotation: 'Check if article has helpful attachments',
                $id: Now.ID['check_has_attachments'],
            },
            () => {
                // High-quality article with attachments - recommend for featuring
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_high_quality_article'],
                        annotation: 'Log high-quality article detection',
                    },
                    {
                        log_level: 'info',
                        log_message: `HIGH QUALITY: Article "${wfa.dataPill(knowledgeArticle.Record.short_description, 'string')}" has comprehensive content with attachments. Recommending for featured status.`,
                    }
                )

                // Create task for knowledge manager to review for featuring
                const featureTask = wfa.action(
                    action.core.createRecord,
                    {
                        $id: Now.ID['create_feature_article_task'],
                        annotation: 'Create task to feature high-quality article',
                    },
                    {
                        table_name: 'task',
                        values: TemplateValue({
                            short_description: `Review Article for Featured Status: ${wfa.dataPill(knowledgeArticle.Record.short_description, 'string')}`,
                            description: `This knowledge article passed QA with high quality indicators (comprehensive content, attachments). Please review for potential featured/promoted status. Article: ${wfa.dataPill(knowledgeArticle.Record.number, 'string')}, Author: ${wfa.dataPill(articleAuthor.Record.name, 'string')}`,
                            priority: 4,
                            state: 1,
                            assigned_to: `${wfa.dataPill(knowledgeManager.Record.sys_id, 'reference')}`,
                        }),
                    }
                )

                // Notify knowledge manager
                wfa.action(
                    action.core.sendNotification,
                    {
                        $id: Now.ID['notify_manager_feature_article'],
                        annotation: 'Notify knowledge manager about high-quality article',
                    },
                    {
                        record: `${wfa.dataPill(featureTask.record, 'reference')}`,
                        notification: 'knowledge_article_feature_candidate',
                    }
                )
            }
        )

        // Step 13: Send QA approval notification to author
        wfa.action(
            action.core.sendNotification,
            {
                $id: Now.ID['notify_author_qa_approved'],
                annotation: 'Notify author of successful QA approval',
            },
            {
                record: `${wfa.dataPill(knowledgeArticle.Record.sys_id, 'reference')}`,
                notification: 'knowledge_article_qa_approved',
            }
        )

        // Step 14: Create QA summary report
        const qaSummaryReport = wfa.action(
            action.core.createRecord,
            {
                $id: Now.ID['create_qa_summary_report'],
                annotation: 'Create QA summary report record',
            },
            {
                table_name: 'task',
                values: TemplateValue({
                    short_description: `Knowledge Article QA Report - ${wfa.dataPill(knowledgeArticle.Record.number, 'string')}`,
                    description: `QA Summary for article "${wfa.dataPill(knowledgeArticle.Record.short_description, 'string')}". Author: ${wfa.dataPill(articleAuthor.Record.name, 'string')}. QA Status: APPROVED. Processed at: ${wfa.dataPill(params.trigger.run_start_date_time, 'datetime')}. Article meets all quality standards.`,
                    priority: 5,
                    state: 1,
                    assigned_to: `${wfa.dataPill(knowledgeManager.Record.sys_id, 'reference')}`,
                }),
            }
        )

        // Step 15: Log completion with statistics
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['log_qa_flow_completion'],
                annotation: 'Log QA flow completion with summary',
            },
            {
                log_level: 'info',
                log_message: `Knowledge Article QA completed successfully. Article: ${wfa.dataPill(knowledgeArticle.Record.number, 'string')}, Title: "${wfa.dataPill(knowledgeArticle.Record.short_description, 'string')}", Status: APPROVED, Report: ${wfa.dataPill(qaSummaryReport.record, 'reference')}`,
            }
        )
    }
)
